with q as (select * from (values
('pcac-national-principles-35','Lei nº 14.735/2023 — princípios','Qual alternativa apresenta princípio institucional básico previsto no art. 4º da Lei nº 14.735/2023?','(A) Sigilo absoluto de todos os atos, sem exceções.\n(B) Hierarquia e disciplina.\n(C) Subordinação da investigação a interesses privados.\n(D) Uso irrestrito da força.\n(E) Divulgação pública obrigatória de técnicas investigativas.','B','O art. 4º inclui hierarquia e disciplina, além de dignidade humana, sigilo necessário, ética, imparcialidade e uso diferenciado da força.'),
('pcac-national-susp-36','Lei nº 14.735/2023 — Susp','As Polícias Civis integram operacionalmente:','(A) apenas o sistema penitenciário estadual.\n(B) o Sistema Único de Segurança Pública (Susp).\n(C) exclusivamente o Poder Judiciário.\n(D) o Ministério Público.\n(E) as Forças Armadas.','B','O art. 2º estabelece que as Polícias Civis integram operacionalmente o Susp.'),
('pcac-national-officer-role-37','Lei nº 14.735/2023 — atribuições do Oficial Investigador','Segundo o art. 27 da Lei nº 14.735/2023, o Oficial Investigador exerce suas atribuições:','(A) presidindo privativamente o inquérito policial.\n(B) sem coordenação da autoridade policial.\n(C) sob determinação ou coordenação do Delegado, dentro de suas atribuições legais, com atuação técnica e científica.\n(D) substituindo o perito oficial em qualquer exame.\n(E) exclusivamente em tarefas administrativas.','C','O art. 27 descreve funções apuratórias, cartorárias, procedimentais, de inteligência e ações investigativas sob determinação ou coordenação do Delegado.'),
('pcac-national-duty-38','Lei nº 14.735/2023 — deveres','Qual dos seguintes é dever expresso dos policiais civis no art. 33 da Lei nº 14.735/2023?','(A) Divulgar técnicas investigativas fora da esfera policial.\n(B) Atender servidores e público em geral com presteza.\n(C) Desobedecer determinações legais.\n(D) Utilizar patrimônio público em interesse particular.\n(E) Abandonar capacitação profissional.','B','O art. 33, V, determina respeito e atendimento com presteza aos demais servidores e ao público em geral.'),
('pcac-lc39-duty-39','LC nº 39/1993 — deveres','Conforme o art. 166 da LC nº 39/1993, é dever do servidor:','(A) cumprir ordens superiores mesmo quando manifestamente ilegais.\n(B) guardar sigilo sobre assunto da repartição.\n(C) usar bens públicos em atividade particular.\n(D) recusar atendimento ao público.\n(E) omitir irregularidades conhecidas no exercício do cargo.','B','O art. 166 prevê expressamente o dever de guardar sigilo sobre assunto da repartição; ordens manifestamente ilegais são exceção ao dever de cumprimento.'),
('pcac-lc39-prohibition-40','LC nº 39/1993 — proibições','A LC nº 39/1993 proíbe expressamente:','(A) comunicar irregularidade à autoridade superior.\n(B) atender o público com urbanidade.\n(C) utilizar pessoal ou recursos materiais da repartição em serviços ou atividades particulares.\n(D) conservar o patrimônio público.\n(E) manter sigilo funcional.','C','A proibição consta do art. 167, XVI.'),
('pcac-lc39-prescription-41','LC nº 39/1993 — prescrição','Qual o prazo prescricional previsto no art. 193 da LC nº 39/1993 para infração punível com advertência?','(A) 30 dias.\n(B) 90 dias.\n(C) 180 dias.\n(D) 2 anos.\n(E) 5 anos.','C','O art. 193, III, estabelece 180 dias para advertência.'),
('pcac-lc39-syndicance-42','LC nº 39/1993 — sindicância','O prazo de conclusão da sindicância previsto no art. 196 da LC nº 39/1993 é de:','(A) 10 dias, sem prorrogação.\n(B) 15 dias, prorrogáveis por 15.\n(C) 30 dias, prorrogáveis por igual período, a critério da autoridade superior.\n(D) 60 dias, prorrogáveis por 60.\n(E) 90 dias.','C','O art. 196, parágrafo único, prevê 30 dias e prorrogação por igual período.'),
('pcac-pccr-progression-43','PCCR — progressão e promoção','Na estrutura de carreira, progressão e promoção se distinguem porque:','(A) ambas significam mudança de órgão.\n(B) progressão muda a referência salarial dentro da mesma classe; promoção eleva para a classe seguinte.\n(C) progressão eleva a classe e promoção muda apenas a referência.\n(D) ambas dependem exclusivamente de sorteio.\n(E) não há distinção legal.','B','O art. 15 da Lei nº 2.250/2009 define progressão como mudança de referência dentro da mesma classe; a Lei nº 3.228/2017 define promoção como passagem à classe imediatamente superior.'),
('pcac-pccr-promotion-44','Lei nº 3.228/2017 — promoção','Entre os requisitos previstos para promoção na Lei nº 3.228/2017, está:','(A) interstício de 12 meses e ausência de avaliação.\n(B) 36 meses na classe, avaliação média mínima de 80 pontos e 120 horas de capacitação, conforme a classe e regulamento.\n(C) apenas aprovação em novo concurso.\n(D) mudança automática a cada ano.\n(E) inexistência de requisito disciplinar.','B','O art. 11 da Lei nº 3.228/2017 estabelece interstício de 36 meses, avaliação e capacitação mínima de 120 horas, além de requisitos específicos por classe.')
) as t(external_item_key,subtopic,question_text,options_text,answer,explanation))
